RESET ROLE; SET LOCAL request.jwt.claims='{"role":"authenticated","sub":"97000000-0000-0000-0000-000000000021"}'; SET LOCAL ROLE authenticated;
DO $$ DECLARE deleted boolean:=false; BEGIN
  BEGIN PERFORM public.delete_my_account(); deleted:=true;
  EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  PERFORM pg_temp.staff_assert('existing coach account deletion remains usable',deleted);
END $$;
